import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"CAF Migrate readiness — enumerated source (formerly the Strategic Migration Assessment)","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/smart-question-set.md","filePath":"frameworks/smart-question-set.md"}'),d={name:"frameworks/smart-question-set.md"};function i(n,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="caf-migrate-readiness-—-enumerated-source-formerly-the-strategic-migration-assessment" tabindex="-1">CAF Migrate readiness — enumerated source (formerly the Strategic Migration Assessment) <a class="header-anchor" href="#caf-migrate-readiness-—-enumerated-source-formerly-the-strategic-migration-assessment" aria-label="Permalink to &quot;CAF Migrate readiness — enumerated source (formerly the Strategic Migration Assessment)&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/plan/" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cloud-adoption-framework/plan/</a> and <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/migrate/plan-migration" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cloud-adoption-framework/migrate/plan-migration</a> (CAF Plan and CAF Migrate, every page named in the tables below) <strong>Framework version:</strong> Not versioned by Microsoft — CAF Plan and CAF Migrate are living documentation with no published release number. Treat the extraction date below as the version. <strong>Extracted:</strong> 2026-11-24 <strong>Verification method:</strong> Manual read of each CAF Plan and CAF Migrate page cited in the tables below, on the extraction date. The retired SMART tool&#39;s own question text was never published and cannot be checked — see the warning below.</p></blockquote><p><strong>Enumerated 2026-11-24. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><h2 id="why-this-page-changed" tabindex="-1">Why this page changed <a class="header-anchor" href="#why-this-page-changed" aria-label="Permalink to &quot;Why this page changed&quot;">​</a></h2><p>Microsoft deletes the <strong>Strategic Migration Assessment and Readiness Tool</strong> (SMART) in January 2027 (<a href="https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/" target="_blank" rel="noreferrer">https://learn.microsoft.com/assessments/Strategic-Migration-Assessment/</a>). It was a 15-minute multiple-choice readiness questionnaire listed under <strong>Plan</strong> in the Cloud Adoption Framework&#39;s tools and templates, whose description named its subject areas: <em>&quot;business planning, training, security, and governance.&quot;</em></p><p>Scout&#39;s assessment of this name was never a copy of SMART — Microsoft did not publish SMART&#39;s questions, so Scout enumerated the CAF content SMART drew on. That content still exists. This page now enumerates it directly, from <strong>CAF Plan</strong> and <strong>CAF Migrate</strong>, and extends it to cover the whole migration sequence: plan, prepare, execute, optimise, decommission.</p><p>The <code>SMART-*</code> identifiers are kept, unchanged, for the items that existed before the re-base, so questionnaire answer files already saved against them keep working. New items continue the same scheme. The assessment itself is now named <strong>CAF: Migrate readiness</strong>, and <code>Microsoft: SMART Migration</code> and <code>SMART</code> remain accepted as aliases.</p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. <code>smart.migration.yaml</code> is written against this enumeration and nothing else, and every rule in it cites an item number from the tables below.</p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-11-24):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>CAF <em>Plan your migration</em> (<code>migrate/plan-migration</code>)</td><td>The five-step sequence, readiness and skills, data migration path, wave sequencing, migration method, rollback plan, stakeholder approval</td></tr><tr><td>CAF <em>Migration wave planning</em> (<code>migrate/migration-wave-planning</code>)</td><td>Grouping workloads into waves</td></tr><tr><td>CAF <em>Select your cloud migration strategies</em> (<code>plan/select-cloud-migration-strategy</code>)</td><td>The 8 R&#39;s and the business-driver-to-strategy mapping</td></tr><tr><td>CAF <em>Assess your workloads for cloud migration</em> (<code>plan/assess-workloads-for-cloud-migration</code>)</td><td>Discovery and assessment tooling, dependencies, compliance, SLA/RPO/RTO, application code, databases, risk register</td></tr><tr><td>CAF <em>Discover your existing workload inventory</em> (<code>plan/discover-existing-workload-inventory</code>)</td><td>The workload inventory and the discovery tools</td></tr><tr><td>CAF <em>Migration adoption plan</em> (<code>plan/migration-adoption-plan</code>)</td><td>Per-workload business details and management group placement</td></tr><tr><td>CAF <em>Prepare your organization for the cloud</em> and <em>Prepare your people for the cloud</em> (<code>plan/</code>)</td><td>Cloud responsibilities, skills</td></tr><tr><td>CAF <em>Prepare workloads for the cloud</em> (<code>migrate/prepare-workloads-cloud</code>)</td><td>Environment subscriptions, compatibility, testing, infrastructure as code</td></tr><tr><td>CAF <em>Execute migration to cloud</em> (<code>migrate/execute-migration</code>)</td><td>Change freeze, cutover, data integrity, fallback, stabilisation</td></tr><tr><td>CAF <em>Optimize workloads after migration</em> (<code>migrate/optimize-workloads-after-migration</code>)</td><td>Monitoring, cost, backup validation, hybrid dependencies</td></tr><tr><td>CAF <em>Decommission source workloads</em> (<code>migrate/decommission-source-workload</code>)</td><td>Approval and data retention</td></tr></tbody></table><p><strong>⚠️ What this is not.</strong> Microsoft&#39;s SMART question text and numbering were never published — SMART was delivered only as an interactive assessment, and the identifiers below are <strong>Scout&#39;s</strong>, not Microsoft&#39;s. This enumeration is the CAF content a migration-readiness review rests on, not a transcription of the retired tool. Any coverage percentage published against this file must say so.</p><p><strong>Product name.</strong> Microsoft&#39;s Azure Migrate documentation now calls the product <strong>Azure Catalyst</strong>. The Azure resource types are unchanged (<code>microsoft.migrate/*</code>), so Scout&#39;s queries still match. Where the tables say &quot;Azure Migrate&quot;, read either name.</p><p><strong>One source is a product page, not CAF.</strong> SMART-C6 (public network access on a migrate project) has no current CAF source. It is checked against the product guide <a href="https://learn.microsoft.com/azure/migrate/how-to-use-azure-migrate-with-private-endpoints" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/migrate/how-to-use-azure-migrate-with-private-endpoints</a>, which also says the project may need to allow traffic from all networks. That is why Scout asks the question and shows evidence instead of scoring it Fail.</p><p><strong>Shelf life.</strong> Microsoft is actively rewriting CAF pages (see the audit&#39;s §8 currency warnings). Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><p>All sources are under <code>https://learn.microsoft.com/azure/cloud-adoption-framework/</code>. &quot;Evidence&quot; says what Scout reads. <strong>Manual</strong> items are questions for the customer; a tool reading ARM cannot evidence whether a business case was agreed.</p><h3 id="a-—-business-planning-and-strategy-caf-plan" tabindex="-1">A — Business planning and strategy (CAF Plan) <a class="header-anchor" href="#a-—-business-planning-and-strategy-caf-plan" aria-label="Permalink to &quot;A — Business planning and strategy (CAF Plan)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-A1</td><td>Business goals for the migration are defined and agreed with stakeholders</td><td><code>plan/select-cloud-migration-strategy#determine-business-drivers-before-migration</code></td><td>Manual</td></tr><tr><td>SMART-A2</td><td>A business driver is identified per workload, and maps to one of the 8 R&#39;s</td><td><code>plan/select-cloud-migration-strategy#determine-business-drivers-before-migration</code></td><td>Manual</td></tr><tr><td>SMART-A3</td><td>A gap analysis exists between each workload&#39;s current and target state</td><td><code>plan/select-cloud-migration-strategy#determine-business-drivers-before-migration</code></td><td>Manual</td></tr><tr><td>SMART-A4</td><td>Migration waves are sequenced lowest-risk first</td><td><code>migrate/plan-migration#determine-the-migration-sequence</code>, <code>migrate/migration-wave-planning</code></td><td>Manual</td></tr><tr><td>SMART-A5</td><td>The cloud operating model and responsibilities are defined</td><td><code>plan/prepare-organization-for-cloud#plan-your-cloud-responsibilities</code></td><td>Manual</td></tr><tr><td>SMART-A6</td><td>A cost estimate exists for the target Azure architecture</td><td><code>plan/estimate-total-cost-of-ownership</code></td><td>Manual</td></tr></tbody></table><p>SMART-A4 previously cited <code>migrate/concepts-migration-planning</code>. That page is an Azure Migrate product page, not CAF, and is no longer used.</p><h3 id="b-—-people-skills-and-training" tabindex="-1">B — People, skills and training <a class="header-anchor" href="#b-—-people-skills-and-training" aria-label="Permalink to &quot;B — People, skills and training&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-B1</td><td>The team&#39;s Azure and migration-tooling skills have been evaluated</td><td><code>migrate/plan-migration#assess-migration-readiness-and-skills</code></td><td>Manual</td></tr><tr><td>SMART-B2</td><td>External expertise is engaged where a capability gap was found</td><td><code>migrate/plan-migration#assess-migration-readiness-and-skills</code>, <code>plan/prepare-people-for-cloud</code></td><td>Manual</td></tr></tbody></table><h3 id="c-—-discovery-assessment-and-tooling" tabindex="-1">C — Discovery, assessment and tooling <a class="header-anchor" href="#c-—-discovery-assessment-and-tooling" aria-label="Permalink to &quot;C — Discovery, assessment and tooling&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-C1</td><td>An Azure Migrate project exists for the estate being migrated</td><td><code>plan/discover-existing-workload-inventory#discover-workload-inventory</code></td><td>Automated — <code>Migration/AzureMigrateProjects</code></td></tr><tr><td>SMART-C2</td><td>Discovery is running — a discovery site is registered</td><td><code>plan/discover-existing-workload-inventory#discover-workload-inventory</code>, tool table in <code>plan/assess-workloads-for-cloud-migration</code></td><td>Automated — <code>Migration/AzureMigrateDiscoverySites</code></td></tr><tr><td>SMART-C3</td><td>Assessments have been created, not just a project</td><td><code>plan/assess-workloads-for-cloud-migration</code></td><td>Automated — assessment projects</td></tr><tr><td>SMART-C4</td><td>Database workloads have a migration path — DMS or an equivalent</td><td><code>plan/assess-workloads-for-cloud-migration#assess-databases</code>, <code>migrate/execute-migration</code></td><td>Automated — <code>Migration/DatabaseMigrationServices</code></td></tr><tr><td>SMART-C5</td><td>Bulk data transfer is planned where the volume needs it (Data Box / Stack Edge)</td><td><code>migrate/plan-migration#choose-your-data-migration-path</code></td><td>Manual, pre-filled with any Data Box or Stack Edge found</td></tr><tr><td>SMART-C6</td><td>Azure Migrate project public network access has been reviewed</td><td>Product guide (no current CAF source), see above</td><td>Manual, pre-filled with projects that allow public access</td></tr><tr><td>SMART-C7</td><td>A private migration path exists — an ExpressRoute circuit or a VPN gateway</td><td><code>migrate/plan-migration#choose-your-data-migration-path</code></td><td>Automated — <code>Networking/ExpressRouteCircuits</code>, <code>Networking/VirtualNetworkGateways</code></td></tr></tbody></table><p>SMART-C5 reads its evidence but does not score it: CAF ranks the data migration path as ExpressRoute, then VPN, then Data Box for large offline transfers, then the public internet for non-sensitive data. Having no Data Box is not a failure.</p><p>SMART-C6 was previously an automated check that failed when public access was enabled. It is now manual, because enabling private endpoints can still leave the project allowing traffic from all networks, which contradicts the old assertion.</p><h3 id="d-—-landing-zone-readiness-caf-ready-prerequisite-of-migrate-plan-migration" tabindex="-1">D — Landing zone readiness (CAF Ready, prerequisite of <code>migrate/plan-migration</code>) <a class="header-anchor" href="#d-—-landing-zone-readiness-caf-ready-prerequisite-of-migrate-plan-migration" aria-label="Permalink to &quot;D — Landing zone readiness (CAF Ready, prerequisite of `migrate/plan-migration`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-D1</td><td>An Azure landing zone exists before workloads are migrated into it</td><td><code>migrate/plan-migration</code> prerequisites (CAF Ready)</td><td>Manual — use the <code>CAF: Azure Landing Zone</code> assessment</td></tr><tr><td>SMART-D2</td><td>Target subscriptions are organised under a management group hierarchy</td><td><code>plan/migration-adoption-plan</code>, <code>migrate/prepare-workloads-cloud#deploy-all-workload-resources</code></td><td>Automated — <code>Management/ManagementGroups</code></td></tr><tr><td>SMART-D3</td><td>Workload environments are separated across subscriptions</td><td><code>migrate/prepare-workloads-cloud#deploy-all-workload-resources</code></td><td>Automated — subscription count (see note)</td></tr><tr><td>SMART-D4</td><td>Role-based access control is assigned in the target scope</td><td><code>migrate/prepare-workloads-cloud#deploy-all-workload-resources</code></td><td>Automated — <code>governance.roleAssignments</code></td></tr><tr><td>SMART-D5</td><td>A cost management budget exists for the target scope</td><td><code>migrate/prepare-workloads-cloud#deploy-all-workload-resources</code>, <code>migrate/optimize-workloads-after-migration#validate-cost-monitoring</code></td><td>Automated — <code>governance.budgets</code></td></tr></tbody></table><p>SMART-D3 counts the subscriptions Scout scanned. It does not read which environment each hosts, so a scan scoped to a single subscription fails it by construction.</p><h3 id="e-—-security" tabindex="-1">E — Security <a class="header-anchor" href="#e-—-security" aria-label="Permalink to &quot;E — Security&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-E1</td><td>Migrated servers land under Defender for Cloud coverage</td><td><code>migrate/prepare-workloads-cloud#resolve-compatibility-issues</code>, <code>migrate/optimize-workloads-after-migration</code></td><td>Automated — <code>Security/DefenderPricing</code></td></tr><tr><td>SMART-E2</td><td>Target resources use private connectivity where required</td><td><code>migrate/plan-migration#choose-your-data-migration-path</code></td><td>Automated — <code>networking.privateEndpoints</code>; the <code>xr.*</code> rules score per-resource coverage</td></tr></tbody></table><h3 id="f-—-governance-and-recovery" tabindex="-1">F — Governance and recovery <a class="header-anchor" href="#f-—-governance-and-recovery" aria-label="Permalink to &quot;F — Governance and recovery&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-F1</td><td>Policy is applied to the target scope before workloads arrive</td><td><code>migrate/prepare-workloads-cloud#deploy-all-workload-resources</code>, <code>plan/prepare-organization-for-cloud#plan-your-cloud-responsibilities</code></td><td>Automated — <code>Management/PolicyComplianceStates</code></td></tr><tr><td>SMART-F2</td><td>Migrated workloads are brought under backup protection</td><td><code>migrate/optimize-workloads-after-migration#validate-critical-configurations</code></td><td>Automated — virtual machines joined to backup protected items (same evidence as <code>XR-BKP-01</code>)</td></tr></tbody></table><h3 id="g-—-workload-assessment-caf-plan" tabindex="-1">G — Workload assessment (CAF Plan) <a class="header-anchor" href="#g-—-workload-assessment-caf-plan" aria-label="Permalink to &quot;G — Workload assessment (CAF Plan)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-G1</td><td>A workload inventory exists with business details for each workload</td><td><code>plan/discover-existing-workload-inventory</code>, <code>plan/migration-adoption-plan#details-on-each-workload</code></td><td>Manual</td></tr><tr><td>SMART-G2</td><td>Internal and external dependencies are mapped and validated with workload owners</td><td><code>plan/assess-workloads-for-cloud-migration#map-internal-and-external-dependencies</code></td><td>Manual</td></tr><tr><td>SMART-G3</td><td>Regulatory and compliance requirements are identified for each workload</td><td><code>plan/assess-workloads-for-cloud-migration#assess-compliance-and-operational-requirements</code></td><td>Manual</td></tr><tr><td>SMART-G4</td><td>SLAs, RPOs and RTOs are documented for each workload</td><td><code>plan/assess-workloads-for-cloud-migration#assess-compliance-and-operational-requirements</code></td><td>Manual</td></tr><tr><td>SMART-G5</td><td>Application code has been assessed for Azure compatibility</td><td><code>plan/assess-workloads-for-cloud-migration#assess-application-code</code></td><td>Manual</td></tr><tr><td>SMART-G6</td><td>A risk register exists with mitigations, owners and status</td><td><code>plan/assess-workloads-for-cloud-migration#create-and-maintain-a-risk-register</code></td><td>Manual</td></tr><tr><td>SMART-G7</td><td>No workload depends on an operating system that is out of support</td><td><code>plan/assess-workloads-for-cloud-migration#assess-workload-components</code>, <code>migrate/prepare-workloads-cloud#resolve-compatibility-issues</code></td><td>Manual — Scout does not collect the guest OS version</td></tr></tbody></table><h3 id="h-—-migration-plan-and-approval-caf-migrate-plan" tabindex="-1">H — Migration plan and approval (CAF Migrate: plan) <a class="header-anchor" href="#h-—-migration-plan-and-approval-caf-migrate-plan" aria-label="Permalink to &quot;H — Migration plan and approval (CAF Migrate: plan)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-H1</td><td>A migration method is chosen for each workload</td><td><code>migrate/plan-migration#choose-the-migration-method-for-each-workload</code></td><td>Manual</td></tr><tr><td>SMART-H2</td><td>The migration schedule avoids critical business events</td><td><code>migrate/plan-migration#create-a-detailed-migration-schedule</code></td><td>Manual</td></tr><tr><td>SMART-H3</td><td>A rollback plan is defined and has been tested</td><td><code>migrate/plan-migration#define-rollback-plan</code></td><td>Manual</td></tr><tr><td>SMART-H4</td><td>Stakeholders have signed off the migration plan and the rollback authority</td><td><code>migrate/plan-migration#engage-stakeholders-on-migration-plan</code></td><td>Manual</td></tr></tbody></table><h3 id="i-—-prepare-workloads-caf-migrate-prepare" tabindex="-1">I — Prepare workloads (CAF Migrate: prepare) <a class="header-anchor" href="#i-—-prepare-workloads-caf-migrate-prepare" aria-label="Permalink to &quot;I — Prepare workloads (CAF Migrate: prepare)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-I1</td><td>Managed identities are in use instead of hard-coded accounts</td><td><code>migrate/prepare-workloads-cloud#resolve-compatibility-issues</code></td><td>Automated — user-assigned identities only (see note)</td></tr><tr><td>SMART-I2</td><td>Network Watcher is available to validate connectivity</td><td><code>migrate/prepare-workloads-cloud#validate-network-connectivity</code></td><td>Automated — <code>Networking/NetworkWatchers</code></td></tr><tr><td>SMART-I3</td><td>Azure Load Testing is available to validate performance</td><td><code>migrate/prepare-workloads-cloud#conduct-functional-and-performance-testing</code></td><td>Automated — load testing resources</td></tr><tr><td>SMART-I4</td><td>Functional, performance and user acceptance testing passed in the test environment</td><td><code>migrate/prepare-workloads-cloud#validate-workload-functionality</code></td><td>Manual</td></tr><tr><td>SMART-I5</td><td>Infrastructure is defined as code and held in version control</td><td><code>migrate/prepare-workloads-cloud#create-reusable-infrastructure</code></td><td>Manual</td></tr></tbody></table><p>SMART-I1 reads user-assigned managed identities only. System-assigned identities on individual resources are not collected, so an estate that uses only those fails the rule without being wrong. SMART-I2 reports whether any Network Watcher exists; it does not check every target region. SMART-I3 is an existence check, and another load-testing tool is an acceptable alternative.</p><h3 id="j-—-execute-migration-caf-migrate-execute" tabindex="-1">J — Execute migration (CAF Migrate: execute) <a class="header-anchor" href="#j-—-execute-migration-caf-migrate-execute" aria-label="Permalink to &quot;J — Execute migration (CAF Migrate: execute)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-J1</td><td>A change freeze is in force on the source systems during the migration window</td><td><code>migrate/execute-migration#implement-a-change-freeze</code></td><td>Manual</td></tr><tr><td>SMART-J2</td><td>Data integrity is validated after cutover</td><td><code>migrate/execute-migration#execute-cutover</code></td><td>Manual</td></tr><tr><td>SMART-J3</td><td>The source environment is kept as a fallback through the stabilisation period</td><td><code>migrate/execute-migration#maintain-fallback-option</code></td><td>Manual</td></tr><tr><td>SMART-J4</td><td>Stabilisation support is staffed and the CMDB is updated</td><td><code>migrate/execute-migration#support-workload-during-stabilization</code></td><td>Manual</td></tr></tbody></table><h3 id="k-—-optimise-and-decommission-caf-migrate" tabindex="-1">K — Optimise and decommission (CAF Migrate) <a class="header-anchor" href="#k-—-optimise-and-decommission-caf-migrate" aria-label="Permalink to &quot;K — Optimise and decommission (CAF Migrate)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Source</th><th>Evidence</th></tr></thead><tbody><tr><td>SMART-K1</td><td>Alert rules exist to monitor migrated workloads</td><td><code>migrate/optimize-workloads-after-migration#validate-workload-monitoring</code></td><td>Automated — metric, log-search and activity-log alert rules</td></tr><tr><td>SMART-K2</td><td>Azure Hybrid Benefit is applied to eligible Windows Server virtual machines</td><td><code>plan/assess-workloads-for-cloud-migration</code>, <code>migrate/decommission-source-workload#azure-tools-and-resources</code></td><td>Automated — <code>compute.virtualMachines</code> license type</td></tr><tr><td>SMART-K3</td><td>On-premises dependencies that cannot migrate are brought under Azure Arc</td><td><code>migrate/plan-migration#address-split-environment-operations</code>, <code>migrate/optimize-workloads-after-migration#optimize-hybrid-and-multicloud-dependencies</code></td><td>Manual, pre-filled with Arc-enabled servers found</td></tr><tr><td>SMART-K4</td><td>Decommissioning of source workloads has formal stakeholder approval</td><td><code>migrate/decommission-source-workload#obtain-stakeholder-approval-before-decommissioning</code></td><td>Manual</td></tr><tr><td>SMART-K5</td><td>Data that stays behind is classified and archived to meet retention obligations</td><td><code>migrate/decommission-source-workload#preserve-data-for-compliance-and-recovery-needs</code></td><td>Manual</td></tr></tbody></table><p>SMART-K2 cannot see licence entitlements: a Windows VM with no license type is a candidate, not proof of overpayment. SMART-K3 never fails — an estate with nothing to keep on-premises has no Arc servers and nothing wrong.</p><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>There are 49 items. 18 are <strong>automated</strong> — a tool reading ARM can evidence them. 31 are <strong>manual</strong> because the answer is an agreement, a plan, a sign-off or a test result that lives outside Azure. <code>smart.migration.yaml</code> marks those <code>manual: true</code> with the item cited, so they appear in the report as questions for the customer rather than silently disappearing, and they are answerable from a questionnaire answers file whether or not any migration data was collected. That is the difference between &quot;18 of 49 automatable&quot; and a fabricated score of 100%.</p><p>When no Azure Migrate project, discovery site or migration service was collected, the rule file&#39;s <code>requires</code> block holds the whole set at Unknown rather than scoring it, because zero unassessed projects and no project at all are the same number and opposite findings. That covers the automated items outside C as well (D to F, I, K), so an estate with no migration data gets no automated score from this assessment; the manual items stay answerable from a questionnaire answers file. A manual item that has evidence (C5, C6, K3) shows it, and never scores its absence.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Rule file: <code>src/assess/rules/smart.migration.yaml</code></li><li>Assessment registry: <code>manifests/assessments.psd1</code> (assessment <code>CAF: Migrate readiness</code>)</li></ul>',50)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
